KG42.register("nodes-0518b410b1e0caee3193f743",{"id":"COMP-44ec202cc152796d","code":"EXE007","label":"Equal-quantity cross-market purchase and sale execution directed by price differences","definition":"LA executes cross-market equal-quantity purchase and sale according to the price spread: when its WEM bus LMP'_o\u003cλ_0, it buys from WEM and resells the same quantity to DNEM; when λ_0\u003cLMP'_o, it buys from DNEM and resells the same quantity to WEM, o∈B_l^o.","layer":"L7","template_code":"JOC","concept_id":"execution.energy_trade","concept_ids":["execution.energy_trade"],"identity_dimensions":{"identity_fields":["Object: the purchase and resale transactions through which the intermediary connects two markets","Core relationship: direction is determined by price comparison, and the purchase quantity equals the resale quantity","Output: cross-market electricity exchange in the corresponding direction"]},"exclusions":["Intermediary: LA","Role 1 corresponds to DNEM import P_l^{imp}, and Role 2 corresponds to DNEM export P_l^{exp}","The direction condition uses strict price inequalities; the source text does not specify behavior when prices are equal","The Case 1 example is purchasing 15 MW from WEM and reselling an equal quantity to DNEM"],"members":[{"id":"23-hierarchical_market_structure::v141-c-R006::V::execution.energy_trade","rule_id":"v141-c-R006","market_meaning":"Selling the awarded 15 MW in the DNEM earns the LA $2100 in Case 1. Scope: The LA's DNEM sale in the worked Case 1 example. Condition: Microgrids have higher marginal generation costs than GENCOs, and the WEM has no congestion.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"The LA's DNEM sale in the worked Case 1 example.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-E19","v141-b-g02-E20","v141-b-g02-E21"]},"constraint_refs":["23-hierarchical_market_structure::v141-c-R006::v141-c-R006-C001"],"decision_anchor":"settlement.payment","source_rule_sha256":"4fc3abd037fab995441d6bf714cf020b1abb05971c1141049c2f093d84e493b7","paper":"23-hierarchical_market_structure","rule_ref":"23-hierarchical_market_structure::v141-c-R006","node_id":"execution.energy_trade","function":"execution.energy_trade","unit_id":"23-hierarchical_market_structure::v141-a-M01::execution.energy_trade","mechanism_id":"v141-a-M01","anchor":false},{"id":"23-hierarchical_market_structure::v141-c-R009::V::execution.energy_trade","rule_id":"v141-c-R009","market_meaning":"The LA's purchase from the WEM and equal-volume resale to the DNEM are conditional on the DNEM price exceeding the WEM bus LMP. Scope: LA role 1: buying electricity from the WEM and selling the same volume to the DNEM. Condition: The LMP at the LA's bus in the WEM is lower than the electricity price in the DNEM. The LA's purchase from the DNEM and equal-volume resale to the WEM are conditional on the DNEM clearing price being below the WEM bus LMP. Scope: LA role 2: purchasing electricity from the DNEM and selling the same volume to the WEM. Condition: The MCP in the DNEM is lower than the LMP at the LA's bus in the WEM.","omega":{"market_type":"LEM_DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"LA role 1: buying electricity from the WEM and selling the same volume to the DNEM. | LA role 2: purchasing electricity from the DNEM and selling the same volume to the WEM.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E009"]},"constraint_refs":["23-hierarchical_market_structure::v141-c-R009::v141-c-R009-C001","23-hierarchical_market_structure::v141-c-R009::v141-c-R009-C002"],"decision_anchor":"execution.energy_trade","source_rule_sha256":"e31c0e34b99cb5e16009768bc25b4d4759d586e8427754c96c85dfb86acbe857","paper":"23-hierarchical_market_structure","rule_ref":"23-hierarchical_market_structure::v141-c-R009","node_id":"execution.energy_trade","function":"execution.energy_trade","unit_id":"23-hierarchical_market_structure::v141-a-M01::execution.energy_trade","mechanism_id":"v141-a-M01","anchor":true}],"paper_ids":["23-hierarchical_market_structure"],"evidence":[{"evidence_id":"v141-b-g02-E19","location":{"location_id":"src-fbc18f73e3-p07-c2r1__v141-a-M01-clearing","page":7,"printed_page":"1872","section":"IV. Case Study","anchor_text":"IEEE TRANSACTIONS ON SMART GRID, VOL. 7, NO. 4, JULY 2016 TABLE III BIDDING STRATEGY AND AWARDED DIS","equation_id":null,"figure_id":null,"table_id":"Table III","image_ref":"pages/page-07.png","occurrence_role":"example"},"source_text":"TABLE III BIDDING STRATEGY AND AWARDED DISPATCH IN CASE 1 | Bidding Strategy: MG1 3.74, MG2 4, LA 1.05, G1 3.64, G2 4 | Awarded Dispatch (MW): MG1 40, MG2 20, LA 15 (imports power), G1 140, G2 135.","paper":"23-hierarchical_market_structure","rule_id":"v141-c-R006","quote":"TABLE III BIDDING STRATEGY AND AWARDED DISPATCH IN CASE 1 | Bidding Strategy: MG1 3.74, MG2 4, LA 1.05, G1 3.64, G2 4 | Awarded Dispatch (MW): MG1 40, MG2 20, LA 15 (imports power), G1 140, G2 135."},{"evidence_id":"v141-b-g02-E20","location":{"location_id":"src-fbc18f73e3-p07-c2r4__v141-a-M01-pricing","page":7,"printed_page":"1872","section":"IV. Case Study","anchor_text":"ed. market. re, Case 3) Lower marginal cost of electricity in microgrids of with no congestion in th","equation_id":null,"figure_id":null,"table_id":"Table III","image_ref":"pages/page-07.png","occurrence_role":"example"},"source_text":"Case 1) Higher Marginal Cost of Electricity in Microgrids With No Congestion in the Wholesale Electricity Market: In this case, the microgrids provide higher marginal cost for electricity compared to the GENCOs as shown in Table II. The bidding strategies and the awarded dispatches for each market participant are listed in Table III. Since there is no congestion in the WEM, the MCP is 80 $/MWh, while the MCP in the DNEM is 140 $/MWh. In this case, the lower price of electricity in the WEM provides incentives for the LA to import electricity from this market to the DNEM.","paper":"23-hierarchical_market_structure","rule_id":"v141-c-R006","quote":"Case 1) Higher Marginal Cost of Electricity in Microgrids With No Congestion in the Wholesale Electricity Market: In this case, the microgrids provide higher marginal cost for electricity compared to the GENCOs as shown in Table II. The bidding strategies and the awarded dispatches for each market participant are listed in Table III. Since there is no congestion in the WEM, the MCP is 80 $/MWh, while the MCP in the DNEM is 140 $/MWh. In this case, the lower price of electricity in the WEM provides incentives for the LA to import electricity from this market to the DNEM."},{"evidence_id":"v141-b-g02-E21","location":{"location_id":"src-fbc18f73e3-p08-c1r2__v141-a-M01-clearing","page":8,"printed_page":"1873","section":"IV. Case Study","anchor_text":"$1200 to purchase 15 MW electricity and earned $2100 by selling the same volume in the DNEM. The exc","equation_id":null,"figure_id":"Fig. 4","table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"example"},"source_text":"$900, $8800, and $8604, respectively. Hence, the LA spent $1200 to purchase 15 MW electricity and earned $2100 by selling the same volume in the DNEM. The exchanged power, the LMP, and the bidding strategies of the market participants in the WEM and the DNEM are illustrated in Fig. 4. In the first iteration an arbitrary large number is assigned as the LMP at the LAs bus in the WEM (1000 $/MWh) and LA bids into the DNEM based on the assigned LMP at the WEM. The awarded dispatch imported to DNEM and the MCP at the DNEM is determined.","paper":"23-hierarchical_market_structure","rule_id":"v141-c-R006","quote":"$900, $8800, and $8604, respectively. Hence, the LA spent $1200 to purchase 15 MW electricity and earned $2100 by selling the same volume in the DNEM. The exchanged power, the LMP, and the bidding strategies of the market participants in the WEM and the DNEM are illustrated in Fig. 4. In the first iteration an arbitrary large number is assigned as the LMP at the LAs bus in the WEM (1000 $/MWh) and LA bids into the DNEM based on the assigned LMP at the WEM. The awarded dispatch imported to DNEM and the MCP at the DNEM is determined."},{"evidence_id":"v141-b-g01-E009","location":{"location_id":"src-fbc18f73e3-p04-c1r1__v141-a-M01-participation","page":4,"printed_page":null,"section":"II-C LAs Objective","anchor_text":"MANSHADI AND KHODAYAR: HIERARCHICAL ELECTRICITY MARKET STRUCTURE electricity from the WEM and sell t","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"Each LA participates in the WEM and the DNEM. The LA acts as a broker playing two different roles: 1) buy electricity from the WEM and sell the same volume to the DNEM, if the LMP on the LAs bus in the WEM is lower than that in the DNEM; and 2) purchase electricity from the DNEM and sell the same volume to the WEM, if the MCP in the DNEM is lower than the LMP on the LAs bus in the WEM.","paper":"23-hierarchical_market_structure","rule_id":"v141-c-R009","quote":"Each LA participates in the WEM and the DNEM. The LA acts as a broker playing two different roles: 1) buy electricity from the WEM and sell the same volume to the DNEM, if the LMP on the LAs bus in the WEM is lower than that in the DNEM; and 2) purchase electricity from the DNEM and sell the same volume to the WEM, if the MCP in the DNEM is lower than the LMP on the LAs bus in the WEM."},{"evidence_id":"v141-b-g01-E010","location":{"location_id":"src-fbc18f73e3-p04-c1r2__v141-a-M01-bidding","page":4,"printed_page":null,"section":"II-C LAs Objective","anchor_text":"of providing electricity to the distribution network. The LAs bidding vector in the DNEM is given in","equation_id":"(7)-(9)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Considering role “1,” LA l maximizes the payoff function which is shown in (7), subjected to the bidding vector constraint (8). Here, LMP' is the marginal price of electricity on the LAs bus in the WEM which is determined as the cost of providing electricity to the distribution network. The LAs bidding vector in the DNEM is given in (9)\nR_l = \\max_{\\psi_l,P_l^{imp}} \\left[ \\left(\\lambda_0 - \\sum_{o\\in B_l^o} LMP'_o\\right) P_l^{imp} \\right] \\tag{7}\n\\underline{\\psi}_l \\le \\psi_l \\le \\bar{\\psi}_l \\tag{8}\n\\rho_l = \\psi_l * \\sum_{o\\in B_l^o} LMP'_o. \\tag{9}","paper":"23-hierarchical_market_structure","rule_id":"v141-c-R009","quote":"Considering role “1,” LA l maximizes the payoff function which is shown in (7), subjected to the bidding vector constraint (8). Here, LMP' is the marginal price of electricity on the LAs bus in the WEM which is determined as the cost of providing electricity to the distribution network. The LAs bidding vector in the DNEM is given in (9)\nR_l = \\max_{\\psi_l,P_l^{imp}} \\left[ \\left(\\lambda_0 - \\sum_{o\\in B_l^o} LMP'_o\\right) P_l^{imp} \\right] \\tag{7}\n\\underline{\\psi}_l \\le \\psi_l \\le \\bar{\\psi}_l \\tag{8}\n\\rho_l = \\psi_l * \\sum_{o\\in B_l^o} LMP'_o. \\tag{9}"},{"evidence_id":"v141-b-g01-E014","location":{"location_id":"src-fbc18f73e3-p04-c1r4__v141-a-M01-clearing","page":4,"printed_page":null,"section":"II-D WEM Clearing Process","anchor_text":"Fb ≤⎝ SFb.Pj + SFb.Pl ⎠ Th o∈Boj o∈Bol lev in , λ′− −SFob.PDo − SFob.Pimpl ≤¯Fb ∀b, λ′+b b in o∈Bol ","equation_id":"(18)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"As shown in (18), the Lagrangian multipliers associated with the load balance and transmission line capacity constraints are employed to calculate the LMPs on each bus in the WEM.\nLMP'_o = \\lambda'_0 + \\sum_b (SF_b^o)^T \\cdot (\\lambda_b^{'+} - \\lambda_b^{'-}). \\tag{18}","paper":"23-hierarchical_market_structure","rule_id":"v141-c-R009","quote":"As shown in (18), the Lagrangian multipliers associated with the load balance and transmission line capacity constraints are employed to calculate the LMPs on each bus in the WEM.\nLMP'_o = \\lambda'_0 + \\sum_b (SF_b^o)^T \\cdot (\\lambda_b^{'+} - \\lambda_b^{'-}). \\tag{18}"},{"evidence_id":"v141-b-g01-E015","location":{"location_id":"src-fbc18f73e3-p04-c2r2__v141-a-M01-clearing","page":4,"printed_page":null,"section":"II-E DNEM Clearing Process","anchor_text":"y As min ρm ∗Pm + ρl ∗Pimpl (19) m l 7) s.t. Pm + Pimpl = PD + Pexpl λ0 (20) m l l 8) P m ≤Pm ≤¯Pm ∀","equation_id":"(19)-(22)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"The DNO minimizes the operational cost of distribution network as shown by\n\\min \\sum_m \\rho_m * P_m + \\sum_l \\rho_l * P_l^{imp} \\tag{19}\ns.t. \\sum_m P_m + \\sum_l P_l^{imp} = P^D + \\sum_l P_l^{exp} \\quad \\lambda_0 \\tag{20}\n\\underline{P}_m \\le P_m \\le \\bar{P}_m \\quad \\forall m \\tag{21}\n\\underline{P}_l^{imp} \\le P_l^{imp} \\le \\bar{P}_l^{imp} \\quad \\forall l. \\tag{22}\nThe load balance in the distribution network is shown in (20). The constraints on the awarded generation for microgrids and the imported power by the LA are shown in (21) and (22), respectively. Here, \\lambda_0 is the Lagrangian multiplier for the generation and load balance constraint in the distribution network as it is assumed that the electricity delivery is not limited by the line congestions.","paper":"23-hierarchical_market_structure","rule_id":"v141-c-R009","quote":"The DNO minimizes the operational cost of distribution network as shown by\n\\min \\sum_m \\rho_m * P_m + \\sum_l \\rho_l * P_l^{imp} \\tag{19}\ns.t. \\sum_m P_m + \\sum_l P_l^{imp} = P^D + \\sum_l P_l^{exp} \\quad \\lambda_0 \\tag{20}\n\\underline{P}_m \\le P_m \\le \\bar{P}_m \\quad \\forall m \\tag{21}\n\\underline{P}_l^{imp} \\le P_l^{imp} \\le \\bar{P}_l^{imp} \\quad \\forall l. \\tag{22}\nThe load balance in the distribution network is shown in (20). The constraints on the awarded generation for microgrids and the imported power by the LA are shown in (21) and (22), respectively. Here, \\lambda_0 is the Lagrangian multiplier for the generation and load balance constraint in the distribution network as it is assumed that the electricity delivery is not limited by the line congestions."},{"evidence_id":"v141-b-g01-E011","location":{"location_id":"src-fbc18f73e3-p04-c1r2__v141-a-M01-bidding","page":4,"printed_page":null,"section":"II-C LAs Objective","anchor_text":"of providing electricity to the distribution network. The LAs bidding vector in the DNEM is given in","equation_id":"(10)-(12)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"R'_l = \\max_{\\psi'_l,P_l^{exp}} \\left[ \\left(\\sum_{o\\in B_l^o} LMP'_o - \\lambda_0\\right) P_l^{exp} \\right] \\tag{10}\n\\underline{\\psi}'_l \\le \\psi'_l \\le \\bar{\\psi}'_l \\tag{11}\n\\rho'_l = \\psi'_l * \\lambda_0. \\tag{12}\nConsidering role “2,” the LA l maximizes the payoff function which is shown in (10), subjected to the constraints on the bidding vector (11). The MCP (\\lambda_0) in the DNEM is the marginal cost of providing electricity to the WEM. The bidding vector of LA l in the WEM is shown in (12).","paper":"23-hierarchical_market_structure","rule_id":"v141-c-R009","quote":"R'_l = \\max_{\\psi'_l,P_l^{exp}} \\left[ \\left(\\sum_{o\\in B_l^o} LMP'_o - \\lambda_0\\right) P_l^{exp} \\right] \\tag{10}\n\\underline{\\psi}'_l \\le \\psi'_l \\le \\bar{\\psi}'_l \\tag{11}\n\\rho'_l = \\psi'_l * \\lambda_0. \\tag{12}\nConsidering role “2,” the LA l maximizes the payoff function which is shown in (10), subjected to the constraints on the bidding vector (11). The MCP (\\lambda_0) in the DNEM is the marginal cost of providing electricity to the WEM. The bidding vector of LA l in the WEM is shown in (12)."}],"candidate_only":true,"classification_subtypes":["conditional_equal_volume_cross_market_trade"],"projection_statuses":["clear"],"taxonomy":{"primary_family":"kind-L7-e22a59fb16","secondary_families":[],"stage":"L7","ontological_kind":"conditional_equal_volume_cross_market_trade"},"semantic_definition":{},"source_units":[{"unit_id":"23-hierarchical_market_structure::v141-a-M01::execution.energy_trade","paper_id":"23-hierarchical_market_structure","mechanism_id":"v141-a-M01","function":"execution.energy_trade","source_occurrences":[{"id":"23-hierarchical_market_structure::v141-c-R006::V::execution.energy_trade","rule_id":"v141-c-R006","market_meaning":"Selling the awarded 15 MW in the DNEM earns the LA $2100 in Case 1. Scope: The LA's DNEM sale in the worked Case 1 example. Condition: Microgrids have higher marginal generation costs than GENCOs, and the WEM has no congestion.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"The LA's DNEM sale in the worked Case 1 example.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-E19","v141-b-g02-E20","v141-b-g02-E21"]},"constraint_refs":["23-hierarchical_market_structure::v141-c-R006::v141-c-R006-C001"],"decision_anchor":"settlement.payment","source_rule_sha256":"4fc3abd037fab995441d6bf714cf020b1abb05971c1141049c2f093d84e493b7"},{"id":"23-hierarchical_market_structure::v141-c-R009::V::execution.energy_trade","rule_id":"v141-c-R009","market_meaning":"The LA's purchase from the WEM and equal-volume resale to the DNEM are conditional on the DNEM price exceeding the WEM bus LMP. Scope: LA role 1: buying electricity from the WEM and selling the same volume to the DNEM. Condition: The LMP at the LA's bus in the WEM is lower than the electricity price in the DNEM. The LA's purchase from the DNEM and equal-volume resale to the WEM are conditional on the DNEM clearing price being below the WEM bus LMP. Scope: LA role 2: purchasing electricity from the DNEM and selling the same volume to the WEM. Condition: The MCP in the DNEM is lower than the LMP at the LA's bus in the WEM.","omega":{"market_type":"LEM_DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"LA role 1: buying electricity from the WEM and selling the same volume to the DNEM. | LA role 2: purchasing electricity from the DNEM and selling the same volume to the WEM.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E009"]},"constraint_refs":["23-hierarchical_market_structure::v141-c-R009::v141-c-R009-C001","23-hierarchical_market_structure::v141-c-R009::v141-c-R009-C002"],"decision_anchor":"execution.energy_trade","source_rule_sha256":"e31c0e34b99cb5e16009768bc25b4d4759d586e8427754c96c85dfb86acbe857"}],"constraints":[{"constraint_id":"v141-c-R006-C001","kind":"mathematical","role":"core","statement":"Selling the awarded 15 MW in the DNEM earns the LA $2100 in Case 1. Scope: The LA's DNEM sale in the worked Case 1 example. Condition: Microgrids have higher marginal generation costs than GENCOs, and the WEM has no congestion.","expression":"\\mathrm{payment}^{DNEM}_{LA,Case1} = \\lambda_0^{Case 1} \\cdot P_l^{imp,Case 1} = 140\\ \\$/MWh \\times 15\\ MW = 2100\\ \\$","formalization_origin":"equivalent_translation","template_id":null,"members":["execution.energy_trade","settlement.payment"],"variable_refs":["v141-c-R006-x-001"],"parameter_refs":["v141-c-R006-theta-001"],"evidence_ids":["v141-b-g02-E19","v141-b-g02-E20","v141-b-g02-E21"],"ref":"23-hierarchical_market_structure::v141-c-R006::v141-c-R006-C001","source_rule_id":"v141-c-R006","evidence":[{"evidence_id":"v141-b-g02-E19","location":{"location_id":"src-fbc18f73e3-p07-c2r1__v141-a-M01-clearing","page":7,"printed_page":"1872","section":"IV. Case Study","anchor_text":"IEEE TRANSACTIONS ON SMART GRID, VOL. 7, NO. 4, JULY 2016 TABLE III BIDDING STRATEGY AND AWARDED DIS","equation_id":null,"figure_id":null,"table_id":"Table III","image_ref":"pages/page-07.png","occurrence_role":"example"},"source_text":"TABLE III BIDDING STRATEGY AND AWARDED DISPATCH IN CASE 1 | Bidding Strategy: MG1 3.74, MG2 4, LA 1.05, G1 3.64, G2 4 | Awarded Dispatch (MW): MG1 40, MG2 20, LA 15 (imports power), G1 140, G2 135."},{"evidence_id":"v141-b-g02-E20","location":{"location_id":"src-fbc18f73e3-p07-c2r4__v141-a-M01-pricing","page":7,"printed_page":"1872","section":"IV. Case Study","anchor_text":"ed. market. re, Case 3) Lower marginal cost of electricity in microgrids of with no congestion in th","equation_id":null,"figure_id":null,"table_id":"Table III","image_ref":"pages/page-07.png","occurrence_role":"example"},"source_text":"Case 1) Higher Marginal Cost of Electricity in Microgrids With No Congestion in the Wholesale Electricity Market: In this case, the microgrids provide higher marginal cost for electricity compared to the GENCOs as shown in Table II. The bidding strategies and the awarded dispatches for each market participant are listed in Table III. Since there is no congestion in the WEM, the MCP is 80 $/MWh, while the MCP in the DNEM is 140 $/MWh. In this case, the lower price of electricity in the WEM provides incentives for the LA to import electricity from this market to the DNEM."},{"evidence_id":"v141-b-g02-E21","location":{"location_id":"src-fbc18f73e3-p08-c1r2__v141-a-M01-clearing","page":8,"printed_page":"1873","section":"IV. Case Study","anchor_text":"$1200 to purchase 15 MW electricity and earned $2100 by selling the same volume in the DNEM. The exc","equation_id":null,"figure_id":"Fig. 4","table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"example"},"source_text":"$900, $8800, and $8604, respectively. Hence, the LA spent $1200 to purchase 15 MW electricity and earned $2100 by selling the same volume in the DNEM. The exchanged power, the LMP, and the bidding strategies of the market participants in the WEM and the DNEM are illustrated in Fig. 4. In the first iteration an arbitrary large number is assigned as the LMP at the LAs bus in the WEM (1000 $/MWh) and LA bids into the DNEM based on the assigned LMP at the WEM. The awarded dispatch imported to DNEM and the MCP at the DNEM is determined."}]},{"constraint_id":"v141-c-R009-C001","kind":"logical","role":"core","statement":"The LA's purchase from the WEM and equal-volume resale to the DNEM are conditional on the DNEM price exceeding the WEM bus LMP. Scope: LA role 1: buying electricity from the WEM and selling the same volume to the DNEM. Condition: The LMP at the LA's bus in the WEM is lower than the electricity price in the DNEM.","expression":"\\left( LMP'_{o} \u003c \\lambda_0 \\right) \\implies \\left( P_l^{imp} > 0 \\right), \\quad o \\in B_l^o","formalization_origin":"equivalent_translation","template_id":null,"members":["execution.energy_trade","pricing.local"],"variable_refs":["v141-c-R009-x001"],"parameter_refs":["v141-c-R009-theta001","v141-c-R009-theta002"],"evidence_ids":["v141-b-g01-E009","v141-b-g01-E010","v141-b-g01-E014","v141-b-g01-E015"],"ref":"23-hierarchical_market_structure::v141-c-R009::v141-c-R009-C001","source_rule_id":"v141-c-R009","evidence":[{"evidence_id":"v141-b-g01-E009","location":{"location_id":"src-fbc18f73e3-p04-c1r1__v141-a-M01-participation","page":4,"printed_page":null,"section":"II-C LAs Objective","anchor_text":"MANSHADI AND KHODAYAR: HIERARCHICAL ELECTRICITY MARKET STRUCTURE electricity from the WEM and sell t","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"Each LA participates in the WEM and the DNEM. The LA acts as a broker playing two different roles: 1) buy electricity from the WEM and sell the same volume to the DNEM, if the LMP on the LAs bus in the WEM is lower than that in the DNEM; and 2) purchase electricity from the DNEM and sell the same volume to the WEM, if the MCP in the DNEM is lower than the LMP on the LAs bus in the WEM."},{"evidence_id":"v141-b-g01-E010","location":{"location_id":"src-fbc18f73e3-p04-c1r2__v141-a-M01-bidding","page":4,"printed_page":null,"section":"II-C LAs Objective","anchor_text":"of providing electricity to the distribution network. The LAs bidding vector in the DNEM is given in","equation_id":"(7)-(9)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Considering role “1,” LA l maximizes the payoff function which is shown in (7), subjected to the bidding vector constraint (8). Here, LMP' is the marginal price of electricity on the LAs bus in the WEM which is determined as the cost of providing electricity to the distribution network. The LAs bidding vector in the DNEM is given in (9)\nR_l = \\max_{\\psi_l,P_l^{imp}} \\left[ \\left(\\lambda_0 - \\sum_{o\\in B_l^o} LMP'_o\\right) P_l^{imp} \\right] \\tag{7}\n\\underline{\\psi}_l \\le \\psi_l \\le \\bar{\\psi}_l \\tag{8}\n\\rho_l = \\psi_l * \\sum_{o\\in B_l^o} LMP'_o. \\tag{9}"},{"evidence_id":"v141-b-g01-E014","location":{"location_id":"src-fbc18f73e3-p04-c1r4__v141-a-M01-clearing","page":4,"printed_page":null,"section":"II-D WEM Clearing Process","anchor_text":"Fb ≤⎝ SFb.Pj + SFb.Pl ⎠ Th o∈Boj o∈Bol lev in , λ′− −SFob.PDo − SFob.Pimpl ≤¯Fb ∀b, λ′+b b in o∈Bol ","equation_id":"(18)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"As shown in (18), the Lagrangian multipliers associated with the load balance and transmission line capacity constraints are employed to calculate the LMPs on each bus in the WEM.\nLMP'_o = \\lambda'_0 + \\sum_b (SF_b^o)^T \\cdot (\\lambda_b^{'+} - \\lambda_b^{'-}). \\tag{18}"},{"evidence_id":"v141-b-g01-E015","location":{"location_id":"src-fbc18f73e3-p04-c2r2__v141-a-M01-clearing","page":4,"printed_page":null,"section":"II-E DNEM Clearing Process","anchor_text":"y As min ρm ∗Pm + ρl ∗Pimpl (19) m l 7) s.t. Pm + Pimpl = PD + Pexpl λ0 (20) m l l 8) P m ≤Pm ≤¯Pm ∀","equation_id":"(19)-(22)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"The DNO minimizes the operational cost of distribution network as shown by\n\\min \\sum_m \\rho_m * P_m + \\sum_l \\rho_l * P_l^{imp} \\tag{19}\ns.t. \\sum_m P_m + \\sum_l P_l^{imp} = P^D + \\sum_l P_l^{exp} \\quad \\lambda_0 \\tag{20}\n\\underline{P}_m \\le P_m \\le \\bar{P}_m \\quad \\forall m \\tag{21}\n\\underline{P}_l^{imp} \\le P_l^{imp} \\le \\bar{P}_l^{imp} \\quad \\forall l. \\tag{22}\nThe load balance in the distribution network is shown in (20). The constraints on the awarded generation for microgrids and the imported power by the LA are shown in (21) and (22), respectively. Here, \\lambda_0 is the Lagrangian multiplier for the generation and load balance constraint in the distribution network as it is assumed that the electricity delivery is not limited by the line congestions."}]},{"constraint_id":"v141-c-R009-C002","kind":"logical","role":"core","statement":"The LA's purchase from the DNEM and equal-volume resale to the WEM are conditional on the DNEM clearing price being below the WEM bus LMP. Scope: LA role 2: purchasing electricity from the DNEM and selling the same volume to the WEM. Condition: The MCP in the DNEM is lower than the LMP at the LA's bus in the WEM.","expression":"\\left( \\lambda_0 \u003c LMP'_{o} \\right) \\implies \\left( P_l^{exp} > 0 \\right), \\quad o \\in B_l^o","formalization_origin":"equivalent_translation","template_id":null,"members":["execution.energy_trade","pricing.local"],"variable_refs":["v141-c-R009-x002"],"parameter_refs":["v141-c-R009-theta001","v141-c-R009-theta002"],"evidence_ids":["v141-b-g01-E009","v141-b-g01-E011","v141-b-g01-E014","v141-b-g01-E015"],"ref":"23-hierarchical_market_structure::v141-c-R009::v141-c-R009-C002","source_rule_id":"v141-c-R009","evidence":[{"evidence_id":"v141-b-g01-E009","location":{"location_id":"src-fbc18f73e3-p04-c1r1__v141-a-M01-participation","page":4,"printed_page":null,"section":"II-C LAs Objective","anchor_text":"MANSHADI AND KHODAYAR: HIERARCHICAL ELECTRICITY MARKET STRUCTURE electricity from the WEM and sell t","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"Each LA participates in the WEM and the DNEM. The LA acts as a broker playing two different roles: 1) buy electricity from the WEM and sell the same volume to the DNEM, if the LMP on the LAs bus in the WEM is lower than that in the DNEM; and 2) purchase electricity from the DNEM and sell the same volume to the WEM, if the MCP in the DNEM is lower than the LMP on the LAs bus in the WEM."},{"evidence_id":"v141-b-g01-E011","location":{"location_id":"src-fbc18f73e3-p04-c1r2__v141-a-M01-bidding","page":4,"printed_page":null,"section":"II-C LAs Objective","anchor_text":"of providing electricity to the distribution network. The LAs bidding vector in the DNEM is given in","equation_id":"(10)-(12)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"R'_l = \\max_{\\psi'_l,P_l^{exp}} \\left[ \\left(\\sum_{o\\in B_l^o} LMP'_o - \\lambda_0\\right) P_l^{exp} \\right] \\tag{10}\n\\underline{\\psi}'_l \\le \\psi'_l \\le \\bar{\\psi}'_l \\tag{11}\n\\rho'_l = \\psi'_l * \\lambda_0. \\tag{12}\nConsidering role “2,” the LA l maximizes the payoff function which is shown in (10), subjected to the constraints on the bidding vector (11). The MCP (\\lambda_0) in the DNEM is the marginal cost of providing electricity to the WEM. The bidding vector of LA l in the WEM is shown in (12)."},{"evidence_id":"v141-b-g01-E014","location":{"location_id":"src-fbc18f73e3-p04-c1r4__v141-a-M01-clearing","page":4,"printed_page":null,"section":"II-D WEM Clearing Process","anchor_text":"Fb ≤⎝ SFb.Pj + SFb.Pl ⎠ Th o∈Boj o∈Bol lev in , λ′− −SFob.PDo − SFob.Pimpl ≤¯Fb ∀b, λ′+b b in o∈Bol ","equation_id":"(18)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"As shown in (18), the Lagrangian multipliers associated with the load balance and transmission line capacity constraints are employed to calculate the LMPs on each bus in the WEM.\nLMP'_o = \\lambda'_0 + \\sum_b (SF_b^o)^T \\cdot (\\lambda_b^{'+} - \\lambda_b^{'-}). \\tag{18}"},{"evidence_id":"v141-b-g01-E015","location":{"location_id":"src-fbc18f73e3-p04-c2r2__v141-a-M01-clearing","page":4,"printed_page":null,"section":"II-E DNEM Clearing Process","anchor_text":"y As min ρm ∗Pm + ρl ∗Pimpl (19) m l 7) s.t. Pm + Pimpl = PD + Pexpl λ0 (20) m l l 8) P m ≤Pm ≤¯Pm ∀","equation_id":"(19)-(22)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"The DNO minimizes the operational cost of distribution network as shown by\n\\min \\sum_m \\rho_m * P_m + \\sum_l \\rho_l * P_l^{imp} \\tag{19}\ns.t. \\sum_m P_m + \\sum_l P_l^{imp} = P^D + \\sum_l P_l^{exp} \\quad \\lambda_0 \\tag{20}\n\\underline{P}_m \\le P_m \\le \\bar{P}_m \\quad \\forall m \\tag{21}\n\\underline{P}_l^{imp} \\le P_l^{imp} \\le \\bar{P}_l^{imp} \\quad \\forall l. \\tag{22}\nThe load balance in the distribution network is shown in (20). The constraints on the awarded generation for microgrids and the imported power by the LA are shown in (21) and (22), respectively. Here, \\lambda_0 is the Lagrangian multiplier for the generation and load balance constraint in the distribution network as it is assumed that the electricity delivery is not limited by the line congestions."}]}],"variables":[{"variable_id":"v141-c-R006-x-001","symbol":"P_l^{imp}","meaning":"Power imported to the DNEM by LA l, i.e. the LA's awarded DNEM sale/injection into the distribution network; in the worked Case 1 this quantity is 15 MW.","kind":"operational","domain":"real scalar [MW], bounded by the source's DNEM import limits in (22); the Case 1 awarded value is 15 MW","unit":"MW","indices":["l"],"evidence_ids":["v141-b-g01-E000","v141-b-g01-E015","v141-b-g02-E19","v141-b-g02-E21"],"source_rule_id":"v141-c-R006","declaration_ref":"23-hierarchical_market_structure::v141-c-R006::x::v141-c-R006-x-001"},{"variable_id":"v141-c-R009-x001","symbol":"P_l^{imp}","meaning":"Power imported to the DNEM by LA l; in role 1 this is the volume bought in the WEM and sold to the DNEM.","kind":"operational","domain":"real-valued power quantity [MW] within the source's stated import bounds","unit":"MW","indices":["l"],"evidence_ids":["v141-b-g01-E000","v141-b-g01-E009","v141-b-g01-E010"],"source_rule_id":"v141-c-R009","declaration_ref":"23-hierarchical_market_structure::v141-c-R009::x::v141-c-R009-x001"},{"variable_id":"v141-c-R009-x002","symbol":"P_l^{exp}","meaning":"Power exported from the DNEM by LA l; in role 2 this is the volume purchased in the DNEM and sold to the WEM.","kind":"operational","domain":"real-valued power quantity [MW] within the source's stated export bounds","unit":"MW","indices":["l"],"evidence_ids":["v141-b-g01-E000","v141-b-g01-E009","v141-b-g01-E011"],"source_rule_id":"v141-c-R009","declaration_ref":"23-hierarchical_market_structure::v141-c-R009::x::v141-c-R009-x002"}],"parameters":[{"parameter_id":"v141-c-R006-theta-001","symbol":"\\lambda_0^{Case 1}","meaning":"Reported DNEM market clearing price (MCP) in Case 1; in the DNEM formulation \\lambda_0 is the Lagrange multiplier of the generation/load-balance constraint (20).","value":{"kind":"numeric","number_value":140.0,"text_value":null},"unit":"$/MWh","indices":[],"evidence_ids":["v141-b-g01-E015","v141-b-g02-E20","v141-b-g02-E21"],"source_rule_id":"v141-c-R006","declaration_ref":"23-hierarchical_market_structure::v141-c-R006::theta::v141-c-R006-theta-001"},{"parameter_id":"v141-c-R009-theta001","symbol":"LMP'_o","meaning":"WEM locational marginal price at bus o, including the LA's bus o in B_l^o; used as the WEM price in the LA role-selection comparison.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"$/MWh","indices":["o"],"evidence_ids":["v141-b-g01-E009","v141-b-g01-E014"],"source_rule_id":"v141-c-R009","declaration_ref":"23-hierarchical_market_structure::v141-c-R009::theta::v141-c-R009-theta001"},{"parameter_id":"v141-c-R009-theta002","symbol":"\\lambda_0","meaning":"DNEM market clearing price (MCP), i.e. the Lagrange multiplier on the DNEM generation-load balance constraint; used as the DNEM price in the LA role-selection comparison.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"$/MWh","indices":[],"evidence_ids":["v141-b-g01-E009","v141-b-g01-E011","v141-b-g01-E015"],"source_rule_id":"v141-c-R009","declaration_ref":"23-hierarchical_market_structure::v141-c-R009::theta::v141-c-R009-theta002"}]}],"source_definitions":[{"unit_id":"23-hierarchical_market_structure::v141-a-M01::execution.energy_trade","stage":"L7","subtype":"conditional_equal_volume_cross_market_trade","projection_status":"clear","target_definition":"LA executes cross-market equal-quantity purchase and sale according to the price spread: when its WEM bus LMP'_o\u003cλ_0, it buys from WEM and resells the same quantity to DNEM; when λ_0\u003cLMP'_o, it buys from DNEM and resells the same quantity to WEM, o∈B_l^o.","form_kind":"procedural","identity_fields":["Object: the purchase and resale transactions through which the intermediary connects two markets","Core relationship: direction is determined by price comparison, and the purchase quantity equals the resale quantity","Output: cross-market electricity exchange in the corresponding direction"],"variation_fields":["Intermediary: LA","Role 1 corresponds to DNEM import P_l^{imp}, and Role 2 corresponds to DNEM export P_l^{exp}","The direction condition uses strict price inequalities; the source text does not specify behavior when prices are equal","The Case 1 example is purchasing 15 MW from WEM and reselling an equal quantity to DNEM"],"constraint_refs":["23-hierarchical_market_structure::v141-c-R006::v141-c-R006-C001","23-hierarchical_market_structure::v141-c-R009::v141-c-R009-C001","23-hierarchical_market_structure::v141-c-R009::v141-c-R009-C002"],"paper_id":"23-hierarchical_market_structure","mechanism_id":"v141-a-M01","function":"execution.energy_trade","template_code":"JOC"}],"source_variants":[],"functional":{"is_child":false,"subdivision_pending":false},"canonical_pointer":"/nodes/80"});
